(function(){
 'use strict';const RI=window.RI,esc=RI.esc;
 const stages=[['start','معرفی','user'],['story','محتوای رزومه','briefcase'],['contact','راه ارتباط','mail'],['look','ظاهر','palette'],['review','مرور و انتشار','rocket']];
 RI.ResumeJourney={
  stages,
  initial(opts={}){
   const key='ri-resume-journey-v1:'+RI.ownerId+':'+RI.workspaceSlot;let saved={};try{saved=JSON.parse(sessionStorage.getItem(key)||'{}')||{};}catch{}
   const explicit=stages.some(([id])=>id===opts.step),legacy=opts.step&&!explicit;
   const c=RI.C(),existing=RI.state.pub.resume.status==='published'||(c.profile.name.trim()&&c.profile.title.trim()&&['experience','education','projects','skills'].some(k=>c[k].length));
   return {key,phase:explicit?opts.step:stages.some(([id])=>id===saved.phase)?saved.phase:'start',guided:legacy?false:explicit?true:typeof saved.guided==='boolean'?saved.guided:!existing};
  },
  remember(state){try{sessionStorage.setItem(state.key,JSON.stringify({phase:state.phase,guided:state.guided}));}catch{}},
  nav(state){return '<div class="journey-bar"><nav aria-label="مسیر ساخت رزومه">'+stages.map(([id,label,icon])=>'<button type="button" data-journey-phase="'+id+'" aria-current="'+(state.phase===id?'step':'false')+'">'+RI.icon(icon)+'<span>'+label+'</span></button>').join('')+'</nav><button type="button" class="btn btn--ghost btn--sm" data-journey-mode>'+RI.icon(state.guided?'section':'sparkle')+(state.guided?'ویرایش مستقیم':'مسیر ساخت')+'</button></div><p class="journey-feedback" role="status" aria-live="polite" data-journey-feedback></p>';},
  story(steps){
   const choices=[['experience','تجربهٔ کاری','کار، کارآموزی یا همکاری'],['projects','پروژه و نمونه‌کار','چیزی که ساخته‌ای'],['education','تحصیلات','رشته و مسیر یادگیری'],['skills','مهارت‌ها','چیزهایی که بلدی'],['template','محتوای همین قالب','سوابق و مهارت‌های داخل قالب'],['certs','دوره و افتخار','دستاوردهای قابل اشاره'],['languages','زبان‌ها','زبان‌هایی که با آن‌ها کار می‌کنی']].filter(([id])=>steps.some(s=>s.id===id));
   return '<section class="journey-story"><h2 tabindex="-1">کدام بخش از تو را نشان بدهیم؟</h2><p>از یکی شروع کن؛ لازم نیست همه را پر کنی.</p><div class="journey-choices">'+choices.map(([id,label,desc])=>{const n=RI.C()[id]?.length;return '<button type="button" class="journey-choice" data-step="'+id+'">'+RI.icon(steps.find(s=>s.id===id).icon)+'<span><b>'+label+'</b><small>'+desc+'</small></span>'+(n?'<span class="chip">'+RI.fa(n)+' مورد</span>':RI.icon('plus'))+'</button>';}).join('')+'</div></section>';
  },
  review(){
   const c=RI.C(),items=RI.readiness().resume.filter(x=>x.req),bad=c.contacts.filter(x=>x.public&&x.value.trim()&&!({email:RI.isEmail,phone:RI.isMobile,website:RI.isUrl}[x.type]?.(x.value)));
   const missing=items.filter(x=>!x.done),template=RI.IMPORTED_TEMPLATES[c.theme.resume],live=RI.state.pub.resume.status==='published';
   return '<section class="journey-review"><h2 tabindex="-1">'+(missing.length||bad.length?'آخرین قدم‌ها تا انتشار':'رزومه‌ات آمادهٔ انتشار است')+'</h2><div class="journey-proof"><span>'+RI.icon('user')+esc(c.profile.name||'نام وارد نشده')+'</span><span>'+RI.icon('palette')+esc(RI.findTemplate('resume',c.theme.resume).name)+'</span><span>'+RI.icon('globe')+'<bdi>'+esc(c.slug?RI.urls().resume:'آدرس انتخاب نشده')+'</bdi></span></div>'+(missing.length?'<ul class="journey-fixes">'+missing.map(x=>'<li>'+RI.icon('edit')+'<span>'+esc(x.label)+'</span>'+(/^(account-first|account-last)$/.test(x.id)?'<button type="button" class="btn btn--soft btn--sm" data-journey-names>تکمیل نام حساب</button>':x.id==='account-phone'?'<button type="button" class="btn btn--soft btn--sm" data-account-phone>تأیید شماره</button>':x.id==='slug'?'<button type="button" class="btn btn--soft btn--sm" data-ready-slug>انتخاب آدرس</button>':x.step==='template'?'<button type="button" class="btn btn--soft btn--sm" data-step="template">بررسی متن قالب</button>':x.route==='resume'?'<button type="button" class="btn btn--soft btn--sm" data-step="'+esc(x.step||'profile')+'">تکمیل</button>':'<a class="btn btn--soft btn--sm" href="'+esc(RI.routeUrl(x.route,{step:x.step,anchor:x.anchor}))+'">تکمیل</a>')+'</li>').join('')+'</ul>':'<p class="journey-ready">'+RI.icon('check')+'پایه‌های انتشار کامل‌اند؛ جزئیات بیشتر به انتخاب توست.</p>')+(bad.length?'<p role="alert">راه تماس عمومی معتبر نیست. <button type="button" class="textlink" data-step="contacts">اصلاح راه تماس</button></p>':'')+(template?'<label class="journey-consent"><input type="checkbox" class="checkbox" data-journey-reviewed '+(RI.resumeValues(c,c.theme.resume).settings.reviewed?'checked':'')+'>متن‌ها، عکس‌ها و اطلاعات نمونهٔ این قالب را بررسی کرده‌ام.</label>':'')+'<div class="btnrow"><button type="button" class="btn btn--soft" data-live>'+RI.icon('eye')+'دیدن رزومه</button><button type="button" class="btn btn--primary" data-journey-publish '+(missing.length||bad.length?'disabled':'')+'>'+RI.icon('rocket')+(live?'به‌روزرسانی رزومه':'انتشار رزومه')+'</button></div><p class="journey-publish-state" role="status"></p><details class="journey-details"><summary>آدرس و تنظیمات بیشتر</summary><a href="/dashboard/publish/?anchor=slug">نام و مسیر صفحه</a><a href="/dashboard/publish/?anchor=share">کارت لینک و جست‌وجو</a></details></section>';
  },
  footer(state){const i=stages.findIndex(([id])=>id===state.phase);return '<footer class="journey-footer"><button type="button" class="btn btn--ghost" data-journey-phase="'+stages[Math.max(0,i-1)][0]+'" '+(!i?'disabled':'')+'>'+RI.icon('chevR')+'قبلی</button><span data-journey-save role="status"></span>'+(i<stages.length-1?'<button type="button" class="btn btn--primary" data-journey-next>'+stages[i+1][1]+RI.icon('chevL')+'</button>':'<button type="button" class="btn btn--ghost" data-journey-phase="story">بازگشت به محتوا</button>')+'</footer>';},
  names(){const a=RI.state.account,owner=RI.ownerId;return RI.modal({title:'نام صاحب حساب',body:['firstName','lastName'].map((key,i)=>'<div class="field"><label class="field__label" for="journey-'+key+'">'+(i?'نام خانوادگی':'نام')+'</label><input class="input" id="journey-'+key+'" maxlength="39" autocomplete="'+(i?'family-name':'given-name')+'" value="'+esc(a[key]||'')+'"></div>').join('')+'<p role="alert" data-name-error></p>',actions:[{label:'انصراف',kind:'ghost'},{label:'ذخیرهٔ نام حساب',kind:'primary',keepOpen:true,onClick:async(modal,event,button)=>{if(button.disabled||owner!==RI.ownerId)return;const values=Object.fromEntries(['firstName','lastName'].map(key=>[key,modal.body.querySelector('#journey-'+key).value.trim()])),error=modal.body.querySelector('[data-name-error]');if(!values.firstName||!values.lastName){error.textContent='نام و نام خانوادگی را کامل کن.';return;}button.disabled=true;try{await RI.accountRequest('account/names',values);if(owner!==RI.ownerId)return;await RI.reloadAccount();modal.close();RI.toast('نام حساب ذخیره شد');}catch(e){error.textContent=e.message;}finally{button.disabled=false;}}}]});}
 };
})();
